package com.hbm.machine.supercomputer;
import com.hbm.energy.*;
import com.hbm.fluid.*;
import com.hbm.fluid.network.*;
import com.hbm.item.battery.*;
import com.hbm.machine.foundry.crucible.ThermalMachine;
import com.hbm.recipe.generic.Blueprints;
import java.math.BigInteger;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.entity.player.*;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;
/** Actual source8slots/5ports/dynamicpowerbudget/whole-jobcoolant, noinventedOC/CCOS. */
public final class SuperComputerEntity extends ThermalMachine implements EnergyReceiver,EnergyConductor,StandardFluidTransceiver,com.hbm.multiblock.MuffledMachine {
 public final FluidTank inputTank=new FluidTank(HbmFluids.NONE,4000),outputTank=new FluidTank(HbmFluids.NONE,4000);public final SuperComputerProcessor computerModule;public BigInteger power=BigInteger.ZERO,maxPower=BigInteger.valueOf(100000);public boolean didProcess,muffled,tilted;private PowerNode node;private FluidPorts ports;
 public SuperComputerEntity(BlockPos pos,BlockState state){super(SuperComputerContent.ENTITY.get(),pos,state,8);computerModule=new SuperComputerProcessor(this,inputTank,outputTank,this,this::recipes);}
 public List<SuperComputerRecipe> recipes(){return level==null?List.of():SuperComputerRecipeConfig.recipes(level.getRecipeManager());}@Override protected String title(){return "container.machineSuperComputer";}@Override public AbstractContainerMenu createMenu(int id,Inventory inventory,Player player){return new SuperComputerMenu(id,inventory,this,worldPosition);}
 public static NodeConnection[] portConnections(BlockPos core,Direction dir){var side=dir.getClockWise();var points=new BlockPos[]{core.relative(dir,8),core.relative(dir,7).relative(side),core.relative(dir,7).relative(side.getOpposite()),core.relative(dir,5).relative(side),core.relative(dir,5).relative(side.getOpposite())};var faces=new Direction[]{dir,side,side.getOpposite(),side,side.getOpposite()};var out=new NodeConnection[5];for(int i=0;i<5;i++)out[i]=new NodeConnection(points[i].relative(faces[i]),faces[i]);return out;}
 public static void tick(Level level,BlockPos pos,BlockState state,SuperComputerEntity machine){if(machine.maxPower.signum()<=0)machine.maxPower=BigInteger.valueOf(1000000);if(!(level instanceof ServerLevel server))return;var connections=portConnections(pos,com.hbm.multiblock.DummyableBlock.facing(state));var positions=Arrays.stream(connections).map(NodeConnection::origin).toArray(BlockPos[]::new);if(machine.node==null||machine.node.isExpired()){machine.node=new PowerNode(positions).setConnections(connections);HbmEnergy.nodespace(server).createNode(machine.node);}if(machine.node.hasValidNet())machine.node.addReceiver(machine);if(machine.ports==null)machine.ports=new FluidPorts(positions,connections);machine.ports.update(server,machine);var recipe=machine.computerModule.getRecipe();if(recipe!=null)machine.maxPower=BigInteger.valueOf(recipe.power()).multiply(BigInteger.valueOf(100));machine.maxPower=machine.maxPower.max(machine.power).max(BigInteger.valueOf(100000));var stack=machine.slots.get(0);if(stack.getItem() instanceof CreativeBatteryItem)machine.power=machine.maxPower;else if(stack.getItem() instanceof HbmBattery battery){var charge=machine.maxPower.subtract(machine.power).min(BigInteger.valueOf(battery.getDischargeRate(stack))).min(BigInteger.valueOf(battery.getCharge(stack)));battery.dischargeBattery(stack,charge.longValueExact());machine.power=machine.power.add(charge);}machine.computerModule.update(1,1,true,machine.slots.get(1));machine.didProcess=machine.computerModule.didProcess;if(machine.computerModule.markDirty)machine.setChanged();machine.sync(100);}
 @Override public boolean canPlaceItem(int slot,ItemStack stack){if(slot==0&&(stack.getItem() instanceof HbmBattery||stack.getItem() instanceof CreativeBatteryItem))return true;if(slot==1&&stack.is(Blueprints.ITEM.get()))return true;return computerModule.isItemValid(slot,stack);}@Override public int[] getSlotsForFace(Direction side){return new int[]{2,3,4,5,6,7};}@Override public boolean canTakeItemThroughFace(int slot,ItemStack stack,Direction side){return slot>=5||computerModule.isSlotClogged(slot);}public void select(String name){computerModule.setRecipe(name,false);setChanged();}
 private static long legacy(BigInteger value){return value.max(BigInteger.valueOf(Long.MIN_VALUE)).min(BigInteger.valueOf(Long.MAX_VALUE)).longValue();}@Override public long getPower(){return legacy(power);}@Override public long getMaxPower(){return legacy(maxPower);}@Override public BigInteger getPowerExact(){return power;}@Override public BigInteger getMaxPowerExact(){return maxPower;}@Override public void setPower(long amount){power=BigInteger.valueOf(amount);}@Override public void setPowerExact(BigInteger amount){power=amount;}@Override public boolean isLoaded(){return !isRemoved()&&level!=null&&level.hasChunkAt(worldPosition);}@Override public boolean canConnect(Direction side){return side!=null;}@Override public PowerNode energyNode(){return node;}@Override public long energyStored(){return getPower();}@Override public long energyCapacity(){return getMaxPower();}@Override public BigInteger energyStoredExact(){return power;}@Override public BigInteger energyCapacityExact(){return maxPower;}
 @Override public FluidTank[] getAllTanks(){return new FluidTank[]{inputTank,outputTank};}@Override public FluidTank[] getReceivingTanks(){return new FluidTank[]{inputTank};}@Override public FluidTank[] getSendingTanks(){return new FluidTank[]{outputTank};}@Override public List<TankView> tanks(){return List.of(new TankView(inputTank.getTankType(),inputTank.getFill(),inputTank.getMaxFill()),new TankView(outputTank.getTankType(),outputTank.getFill(),outputTank.getMaxFill()));}
 private static BigInteger read(CompoundTag tag,String key){return tag.contains(key,8)?new BigInteger(tag.getString(key)):BigInteger.valueOf(tag.getLong(key));}@Override protected void saveMachine(CompoundTag tag){inputTank.writeToNBT(tag,"i");outputTank.writeToNBT(tag,"o");tag.putString("power",power.toString());tag.putString("maxPower",maxPower.toString());tag.putBoolean("muffled",muffled);tag.putBoolean("tilted",tilted);computerModule.writeToNBT(tag);}@Override protected void loadMachine(CompoundTag tag){inputTank.readFromNBT(tag,"i");outputTank.readFromNBT(tag,"o");power=read(tag,"power");maxPower=read(tag,"maxPower");muffled=tag.getBoolean("muffled");tilted=tag.getBoolean("tilted");computerModule.readFromNBT(tag);}@Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=super.getUpdateTag(lookup);tag.putBoolean("didProcess",didProcess);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){super.handleUpdateTag(tag,lookup);didProcess=tag.getBoolean("didProcess");}
 private void disconnect(){if(level instanceof ServerLevel server){if(node!=null&&!node.isExpired())HbmEnergy.nodespace(server).destroyNode(node);if(ports!=null)ports.remove(server);}node=null;ports=null;}@Override public void setRemoved(){disconnect();super.setRemoved();}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}
 @Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;setChanged();}
}
